і ключі.","tree":{"sha":"38447b5179deca480fbf6fce6f8efeae7f7df680","url":"https://api.github.com/repos/ZlyiUkra/docfactory/git/trees/38447b5179deca480fbf6fce6f8efeae7f7df680"},"url":"https://api.github.com/repos/ZlyiUkra/docfactory/git/commits/af9b7d43c19bd525826b76dc3a2c7d2198193490","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/12134884?v=4","events_url":"https://api.github.com/users/AlexGochu/events{/privacy}","followers_url":"https://api.github.com/users/AlexGochu/followers","following_url":"https://api.github.com/users/AlexGochu/following{/other_user}","gists_url":"https://api.github.com/users/AlexGochu/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/AlexGochu","id":12134884,"login":"AlexGochu","node_id":"MDQ6VXNlcjEyMTM0ODg0","organizations_url":"https://api.github.com/users/AlexGochu/orgs","received_events_url":"https://api.github.com/users/AlexGochu/received_events","repos_url":"https://api.github.com/users/AlexGochu/repos","site_admin":false,"starred_url":"https://api.github.com/users/AlexGochu/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/AlexGochu/subscriptions","type":"User","url":"https://api.github.com/users/AlexGochu","user_view_type":"public"},"html_url":"https://github.com/ZlyiUkra/docfactory/commit/af9b7d43c19bd525826b76dc3a2c7d2198193490","node_id":"C_kwDOUNyOMtoAKGFmOWI3ZDQzYzE5YmQ1MjU4MjZiNzZkYzNhMmM3ZDIxOTgxOTM0OTA","parents":[{"html_url":"https://github.com/ZlyiUkra/docfactory/commit/8aa299649742181245ee53a1a085b96ea3a10ee6","sha":"8aa299649742181245ee53a1a085b96ea3a10ee6","url":"https://api.github.com/repos/ZlyiUkra/docfactory/commits/8aa299649742181245ee53a1a085b96ea3a10ee6"}],"sha":"af9b7d43c19bd525826b76dc3a2c7d2198193490","url":"https://api.github.com/repos/ZlyiUkra/docfactory/commits/af9b7d43c19bd525826b76dc3a2c7d2198193490"},{"author":{"avatar_url":"https://avatars.gi