INSERT INTO collection_pages VALUES('ba20871ebb8e328d3cc3d1f5dc8009af6cd3ac400806f8d49bc2c9cffddc7b9b','2e4bc65b0250553d42a559488fa129651ee1d3bf8853e3bf92a77b5e3699d88d','{"hasNext":false,"items":[{"author":{"account":null,"email":"yvvakimoto@ymail.ne.jp","name":"yvvakimoto"},"authoredDate":"2026-09-05T06:22:20Z","committedDate":"2026-09-05T06:22:20Z","committer":{"account":null,"email":"yvvakimoto@ymail.ne.jp","name":"yvvakimoto"},"observedAt":"2026-10-09T00:32:06.300Z","repositoryId":1357892534,"sha":"1b6663c358d8d149c5bef4adcf17c18cac5c34ef"},{"author":{"account":null,"email":"yvvakimoto@ymail.ne.jp","name":"yvvakimoto"},"authoredDate":"2026-09-05T06:17:29Z","committedDate":"2026-09-05T06:17:29Z","committer":{"account":null,"email":"yvvakimoto@ymail.ne.jp","name":"yvvakimoto"},"observedAt":"2026-10-09T00:32:06.300Z","repositoryId":1357892534,"sha":"4a40efba36f767f040e1b34b38e5e30cf0371de8"},{"author":{"account":null,"email":"yvvakimoto@ymail.ne.jp","name":"yvvakimoto"},"authoredDate":"2026-09-05T06:09:00Z","committedDate":"2026-09-05T06:09:00Z","committer":{"account":null,"email":"yvvakimoto@ymail.ne.jp","name":"yvvakimoto"},"observedAt":"2026-10-09T00:32:06.300Z","repositoryId":1357892534,"sha":"69ed8361e0528830a930b05dba31ca496ea963f0"}],"observedAt":"2026-10-09T00:32:06.300Z","raw":[{"author":null,"comments_url":"https://api.github.com/repos/yvvakimoto/jupyterlab-vim-langmap/commits/1b6663c358d8d149c5bef4adcf17c18cac5c34ef/comments","commit":{"author":{"date":"2026-09-05T06:22:20Z","email":"yvvakimoto@ymail.ne.jp","name":"yvvakimoto"},"comment_count":0,"committer":{"date":"2026-09-05T06:22:20Z","email":"yvvakimoto@ymail.ne.jp","name":"yvvakimoto"},"message":"Rewrite the README in English\n\nThe package targets the JupyterLab extension ecosystem, and the README is\nwhat PyPI renders as the project page, so English reaches the audience that\nwould look for this.\n\nCo-Authored-By: Claude Opus 5 <noreply@anthropic.com>","tree":{"sha":"1aff9ddf2367c3fe853df7308629c553b150ac4a","url":"https://api.github.com/repos/yvvakimoto/jupyterlab-vim-langmap/git/trees/1aff9ddf2367c3fe853df7308629c553b150ac4a"},"url":"https://api.github.com/repos/yvvakimoto/jupyterlab-vim-langmap/git/commits/1b6663c358d8d149c5bef4adcf17c18cac5c34ef","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":null,"html_url":"https://github.com/yvvakimoto/jupyterlab-vim-langmap/commit/1b6663c358d8d149c5bef4adcf17c18cac5c34ef","node_id":"C_kwDOUO_LttoAKDFiNjY2M2MzNThkOGQxNDljNWJlZjRhZGNmMTdjMThjYWM1YzM0ZWY","parents":[{"html_url":"https://github.com/yvvakimoto/jupyterlab-vim-langmap/commit/4a40efba36f767f040e1b34b38e5e30cf0371de8","sha":"4a40efba36f767f040e1b34b38e5e30cf0371de8","url":"https://api.github.com/repos/yvvakimoto/jupyterlab-vim-langmap/commits/4a40efba36f767f040e1b34b38e5e30cf0371de8"}],"sha":"1b6663c358d8d149c5bef4adcf17c18cac5c34ef","url":"https://api.github.com/repos/yvvakimoto/jupyterlab-vim-langmap/commits/1b6663c358d8d149c5bef4adcf17c18cac5c34ef"},{"author":null,"comments_url":"https://api.github.com/repos/yvvakimoto/jupyterlab-vim-langmap/commits/4a40efba36f767f040e1b34b38e5e30cf0371de8/comments","commit":{"author":{"date":"2026-09-05T06:17:29Z","email":"yvvakimoto@ymail.ne.jp","name":"yvvakimoto"},"comment_count":0,"committer":{"date":"2026-09-05T06:17:29Z","email":"yvvakimoto@ymail.ne.jp","name":"yvvakimoto"},"message":"Prepare for PyPI release\n\nLint was failing, which would have broken CI on the first push:\n\n- tools/check-langmap.cjs was linted as an ES module with browser globals, so\n  every require() and console call was an error. Give **/*.cjs a CommonJS\n  config block with node globals.\n- The prettier:base glob covered .js but not .cjs, so that file was checked by\n  eslint-plugin-prettier yet never formatted by the prettier scripts.\n- schema/plugin.json used `enum` for `preset`; the Jupyter eslint plugin asks\n  for `oneOf` with `const` and `title` so the settings editor can show\n  translatable labels.\n\nAlso for the PyPI page: a 0.1.0 changelog entry, keywords that reach beyond\nthe three jupyter defaults, and a README link to tools/keylog.html on GitHub\nsince that file is not part of the wheel.\n\nCo-Authored-By: Claude Opus 5 <noreply@anthropic.com>","tree":{"sha":"5502bfe4aa01db32f71d9c58a7ee77b14f6fe11e","url":"https://api.github.com/repos/yvvakimoto/jupyterlab-vim-langmap/git/trees/5502bfe4aa01db32f71d9c58a7ee77b14f6fe11e"},"url":"https://api.github.com/repos/yvvakimoto/jupyterlab-vim-langmap/git/commits/4a40efba36f767f040e1b34b38e5e30cf0371de8","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":null,"html_url":"https://github.com/yvvakimoto/jupyterlab-vim-langmap/commit/4a40efba36f767f040e1b34b38e5e30cf0371de8","node_id":"C_kwDOUO_LttoAKDRhNDBlZmJhMzZmNzY3ZjA0MGUxYjM0YjM4ZTVlMzBjZjAzNzFkZTg","parents":[{"html_url":"https://github.com/yvvakimoto/jupyterlab-vim-langmap/commit/69ed8361e0528830a930b05dba31ca496ea963f0","sha":"69ed8361e0528830a930b05dba31ca496ea963f0","url":"https://api.github.com/repos/yvvakimoto/jupyterlab-vim-langmap/commits/69ed8361e0528830a930b05dba31ca496ea963f0"}],"sha":"4a40efba36f767f040e1b34b38e5e30cf0371de8","url":"https://api.github.com/repos/yvvakimoto/jupyterlab-vim-langmap/commits/4a40efba36f767f040e1b34b38e5e30cf0371de8"},{"author":null,"comments_url":"https://api.github.com/repos/yvvakimoto/jupyterlab-vim-langmap/commits/69ed8361e0528830a930b05dba31ca496ea963f0/comments","commit":{"author":{"date":"2026-09-05T06:09:00Z","email":"yvvakimoto@ymail.ne.jp","name":"yvvakimoto"},"comment_count":0,"committer":{"date":"2026-09-05T06:09:00Z","email":"yvvakimoto@ymail.ne.jp","name":"yvvakimoto"},"message":"Add jupyterlab-vim-langmap extension\n\nRemaps vim command keys back to QWERTY physical positions for users whose\nOS emulates another layout (Dvorak via やまぶきR), while leaving text input\nalone. jupyterlab-vim has no langmap setting of its own, and the mass\n`extraKeybindings` workaround cannot work: commandMatches() switches the\ncontext to \"operatorPending\" while an operator is pending, and the schema\nonly allows normal/insert/visual, so `d` + motion would break.\n\nTwo layers, both driven from a single langmap string:\n\n- vim: Vim.langmap() from @replit/codemirror-vim. It applies in\n  vimKeyFromEvent(), ahead of command matching, so operators, counts and\n  operator-pending come along for free. Character arguments (f/r/m/registers)\n  are excluded by expectLiteralNext, and the Ex and search prompts never see\n  a langmap.\n- JupyterLab: swap the @lumino/keyboard layout, which resolves every Lumino\n  keybinding through _codes[event.keyCode]. One permuted table moves Jupyter\n  Command mode, the command palette and menu mnemonics at once.\n\nThe vim langmap is module-global state, so the extension must reach the same\nmodule instance jupyterlab-vim uses; sharedPackages declares\n@replit/codemirror-vim as `bundled: false` so webpack consumes the copy\njupyterlab-vim contributes to the federation share scope.\n\nThe built-in Dvorak preset is the usual VSCodeVim vim.langmap string plus the\n`{_` and `}+` pairs it omits. Without them the physical `-` and `=` keys still\nemit `{` and `}` when shifted, firing the paragraph motions from a second\nphysical key while `_` and `+` stay unreachable.\n\ntools/keylog.html measures what the browser actually sees under the OS\nremapper, which decides whether applyToJupyterShortcuts is needed.\ntools/check-langmap.cjs checks the parser and asserts the keycode remap is a\npermutation of the main block, so no shortcut becomes unreachable.\n\nCo-Authored-By: Claude Opus 5 <noreply@anthropic.com>","tree":{"sha":"3fc9eecdd6860946dcca75ab992dae3f4540f236","url":"https://api.github.com/repos/yvvakimoto/jupyterlab-vim-langmap/git/trees/3fc9eecdd6860946dcca75ab992dae3f4540f236"},"url":"https://api.github.com/repos/yvvakimoto/jupyterlab-vim-langmap/git/commits/69ed8361e0528830a930b05dba31ca496ea963f0","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":null,"html_url":"https://github.com/yvvakimoto/jupyterlab-vim-langmap/commit/69ed8361e0528830a930b05dba31ca496ea963f0","node_id":"C_kwDOUO_LttoAKDY5ZWQ4MzYxZTA1Mjg4MzBhOTMwYjA1ZGJhMzFjYTQ5NmVhOTYzZjA","parents":[],"sha":"69ed8361e0528830a930b05dba31ca496ea963f0","url":"https://api.github.com/repos/yvvakimoto/jupyterlab-vim-langmap/commits/69ed8361e0528830a930b05dba31ca496ea963f0"}],"requestUrl":"https://api.github.com/repos/yvvakimoto/jupyterlab-vim-langmap/commits?per_page=100&page=1&sha=1b6663c358d8d149c5bef4adcf17c18cac5c34ef&since=2025-03-31T23%3A59%3A59.000Z&until=2026-10-08T16%3A20%3A01.631Z"}');
